from common import *
SUB="Oct 20 roles · 04 tutorial"
V=[
V("o20-march-tests","37.1 · Memory test","March tests: finding broken memory cells",[
S("title",sub=SUB,items=["Fault types","Why order matters","March C-"],say=["This video explains how chip and board engineers find broken memory cells, using a march test.","We start with an analogy, define the fault types, then step through March C minus."]),
S("analogy","Plain analogy: checking every locker in a hallway",items=["Write a note in every locker, then read them all back","A stuck lock always shows the same note","A sticky neighbour changes the locker next door","Walk the hallway both directions to catch both neighbours"],say=["Picture a hallway of lockers, and you must prove every one works.","The simple plan: put a note in every locker, then read every note back.","A broken lock that is stuck always shows the same note. The simple plan catches that.","But some lockers disturb their neighbour when you open them. That is a coupling fault.","To catch a neighbour on either side, you must walk the hallway in both directions, writing and reading as you go. That is a march test."]),
S("terms",items=[("Stuck-at fault","A cell always reads 0 or always reads 1."),("Transition fault","A cell can't change one way, for example from 1 to 0."),("Coupling fault","Writing one cell (the aggressor) flips another (the victim)."),("March element","One pass over all addresses, up or down, doing a fixed list of reads and writes per cell.")],say=["Four words to know.","A stuck-at fault: the cell always reads the same value.","A transition fault: the cell can't change in one direction.","A coupling fault: writing one cell, the aggressor, flips another cell, the victim.","A march element: one pass over every address, going up or down, with the same reads and writes at each cell."]),
S("flow","March C- in six elements",items=["⇕ write 0","⇑ read 0, write 1","⇑ read 1, write 0","⇓ read 0, write 1","⇓ read 1, write 0","⇕ read 0"],subs=["start clean","catches stuck-at-1","catches 1→0 transitions","aggressor above the victim","second direction","final check"],say=["Here is March C minus, element by element.","First, write zero everywhere, in any order.","Going up, read zero then write one. A stuck-at-one cell fails its read here.","Still going up, read one then write zero. A cell that can't fall from one to zero fails here.","Now going down, read zero, write one. Writes from higher addresses reach victims below before they are read.","Going down again, read one, write zero.","Finally read zero everywhere. Ten operations per cell in total, and in the lesson's model a write-all, read-all test misses the coupling fault this catches."]),
S("recap","Recap",items=["Write-all / read-all misses some coupling faults","Direction of each pass decides which neighbour you catch","March C-: 10 operations per cell","Lab: run the lesson 37.1 simulator and inject each fault"],say=["Let's recap.","A simple write-all, read-all test misses some coupling faults.","The direction of each pass decides which neighbour you can catch.","March C minus costs ten operations per cell.","Try it yourself in lesson thirty seven point one."])]),
V("o20-vxlan-mtu","38.2 · Linux networking","VXLAN overlays and the 50-byte MTU tax",[
S("title",sub=SUB,items=["Encapsulation","MTU math","Learning MAC addresses"],say=["This video explains VXLAN, the overlay that lets cloud virtual networks span many physical hosts.","We cover the packet wrapping, the M T U math, and how the forwarding table learns."]),
S("analogy","Plain analogy: a letter inside a courier envelope",items=["Your letter is the original Ethernet frame","The courier puts it in a bigger envelope with a tracking label (VNI)","The courier's truck has a size limit: the MTU","Bigger envelope, less room for your letter"],say=["Think of mailing a letter through a courier.","Your letter is the original Ethernet frame from a virtual machine.","The courier puts it inside a larger envelope with a label saying which customer network it belongs to. That label is the V N I.","The courier's truck only takes packages up to a fixed size. That size is the M T U.","Because the envelope adds size, your letter must be smaller to still fit."]),
S("terms",items=[("VNI","VXLAN Network Identifier, 24 bits: which tenant network a frame belongs to."),("VTEP","VXLAN tunnel endpoint: the host or NIC that wraps and unwraps frames."),("MTU","Largest packet a link carries, often 1500 bytes."),("FDB","Forwarding database: which remote VTEP owns a MAC address.")],say=["Four words.","The V N I is a twenty four bit number naming the tenant network.","A V TEP is the endpoint that wraps and unwraps frames, a host or a smart NIC.","The M T U is the biggest packet a link carries, often fifteen hundred bytes.","The F D B maps a MAC address to the remote V TEP that owns it."]),
S("flow","Where the 50 bytes go (IPv4 underlay)",items=["Outer Ethernet 14","Outer IPv4 20","UDP 8 (port 4789)","VXLAN header 8","Inner frame: 1500 − 50 = 1450 IP MTU"],say=["Let's add up the cost.","Fourteen bytes of outer Ethernet header.","Twenty bytes of outer IPv4.","Eight bytes of UDP, on port forty seven eighty nine.","Eight bytes of VXLAN header with the V N I. The outer Ethernet header doesn't count against the underlay's IP M T U, so the inner Ethernet header is charged instead, and the total is still fifty bytes: on a fifteen hundred byte underlay the inner IP M T U is fourteen fifty. Get this wrong and large packets silently vanish."]),
S("recap","Recap",items=["VXLAN = Ethernet frame inside UDP","VNI separates tenants (24 bits)","Lower inner MTU by 50 or use jumbo frames","FDB learns MAC → VTEP and ages entries","Lab: lesson 38.2 builds and parses the header in C"],say=["Recap.","VXLAN carries an Ethernet frame inside UDP.","The V N I keeps tenants apart.","Lower the inner M T U by fifty, or use jumbo frames underneath.","The F D B learns which V TEP owns each MAC and forgets stale entries.","Lesson thirty eight point two builds this in C."])]),
V("o20-sensor-content","38.3 · Endpoint sensors","Endpoint sensors: process trees and safe content updates",[
S("title",sub=SUB,items=["Process trees","Bounded buffers","Validating content"],say=["This video covers how an endpoint security sensor tracks processes, and how to ship detection updates without crashing machines."]),
S("analogy","Plain analogy: a building's security desk",items=["Every visitor badge records who let them in (parent process)","Suspicious chains, like a delivery person opening the server room","The visitor log has a fixed size; overflow is counted, not ignored","New rule cards are tested at one desk before every desk"],say=["Picture the security desk of a large building.","Every visitor badge records who let them in. That is the parent process.","The guard looks for suspicious chains, like a word processor launching a command shell.","The visitor log has a fixed size. When it's full, the guard counts what was dropped instead of pretending nothing happened.","And when head office sends new rule cards, they are tried at one desk before they go to every desk."]),
S("bullets","Design rules from the lesson",items=["Key processes by (pid, start time): pids get reused","Bound ancestry walks: loops and missing parents happen","Kernel-to-user ring buffer with a drop counter","Validate content against the parser the sensor actually runs","Roll out in rings; fall back to last known-good on repeated crashes"],say=["Five design rules.","Key each process by its pid and start time, because pids get reused.","Bound every walk up the ancestry chain, because data can be missing or looped.","Pass events from kernel to user space through a ring buffer, and count drops.","Validate new content against the same parser the sensor runs. CrowdStrike's public root cause analysis of the July twenty twenty four outage describes a template expecting twenty one fields while the sensor supplied twenty.","Roll out in rings, and fall back to the last known good content after repeated crashes."]),
S("recap","Recap",items=["Process identity = pid + start time","Bounded walks and bounded buffers","Validator must match the real parser","Rings + local fallback","Lab: lesson 38.3; design: 06 sd28"],say=["Recap.","Process identity is pid plus start time.","Keep walks and buffers bounded.","The validator must match the real parser.","Ship in rings with a local fallback.","Practice in lesson thirty eight point three and design sd twenty eight."])]),
V("o20-otel-tail","39.3 · Observability","OpenTelemetry tail sampling and cardinality budgets",[
S("title",sub=SUB,items=["Head vs tail sampling","Deterministic decisions","Label budgets"],say=["This video explains how large fleets keep the important traces without storing everything."]),
S("analogy","Plain analogy: a hospital triage desk",items=["Head sampling: decide at the door, before you know what's wrong","Tail sampling: wait for the whole visit, then decide","Always admit the serious cases (errors, slow)","Admit a fixed share of healthy visits for baselines"],say=["Think of a hospital triage desk.","Head sampling decides at the door, before anyone knows what is wrong.","Tail sampling waits until the whole visit is over, then decides.","Serious cases, errors and slow requests, are always kept.","A fixed share of healthy visits is kept too, so you know what normal looks like."]),
S("flow","Tail-sampling pipeline",items=["SDK emits spans","Load balancer routes by trace ID","Gateway buffers until the root span ends or times out","Decide: error → keep, slow → keep, else hash(trace ID) < N%","Store kept traces"],say=["Here's the pipeline.","Applications emit spans through the OpenTelemetry SDK.","A load balancer sends every span of one trace to the same collector, by hashing the trace ID.","The gateway buffers spans until the root span ends or a timeout passes.","Then it decides. Errors are kept. Slow traces are kept. Otherwise a hash of the trace ID picks a fixed percentage, so every collector makes the same choice.","Kept traces go to storage."]),
S("recap","Recap",items=["Tail sampling needs all spans on one collector","Keep errors and slow traces always","Hash-based sampling is deterministic","Cap label combinations per metric; fold extras into 'other'","Lab: lesson 39.3; design: 06 sd27"],say=["Recap.","Tail sampling needs every span of a trace on one collector.","Always keep errors and slow traces.","Hash-based sampling gives the same decision everywhere.","Cap label combinations per metric so one team can't explode your bill.","Practice in lesson thirty nine point three and design sd twenty seven."])]),
V("o20-outbox-saga","40.1 · Product backends","Outbox, idempotent consumers and sagas",[
S("title",sub=SUB,items=["The dual-write problem","Transactional outbox","Sagas"],say=["This video explains how backends avoid lost or duplicated orders when a database and a message queue must agree."]),
S("analogy","Plain analogy: a restaurant ticket rail",items=["Write the order and the kitchen ticket in one motion","A runner carries tickets; if unsure, they carry it again","The kitchen ignores a ticket number it already cooked","If the delivery can't happen, undo earlier steps in reverse"],say=["Picture a restaurant ticket rail.","The waiter writes the order and the kitchen ticket in one motion, so one can't exist without the other. That is the outbox.","A runner carries tickets to the kitchen. If unsure whether a ticket arrived, they carry it again.","The kitchen ignores any ticket number it already cooked. That is an idempotent consumer.","And if the delivery can't happen, earlier steps are undone in reverse: refund the card, release the table. That is a saga."]),
S("seq","Order flow with a lost acknowledgement",lanes=["Order service + DB","Relay","Consumer"],msgs=[(0,0,"one transaction: insert order + outbox row"),(1,2,"publish event id=order-created-42"),(2,1,"ack lost on the network"),(1,2,"publish same event again"),(2,2,"seen id → skip; applied once"),(1,0,"mark outbox row sent")],say=["Let's walk a failure.","The order and its outbox row are written in one database transaction.","The relay publishes the event with a stable id.","The acknowledgement gets lost.","So the relay publishes the same event again. This is at-least-once delivery.","The consumer has already seen that id, so it skips it. The effect happens once.","Finally the relay marks the row as sent."]),
S("recap","Recap",items=["Never write DB and queue separately","Outbox + relay = at-least-once","Consumers dedupe by event id","Sagas compensate completed steps in reverse","Lab: lesson 40.1; design: 06 sd26"],say=["Recap.","Never write the database and the queue as two separate steps.","Outbox plus relay gives at-least-once delivery.","Consumers dedupe by event id.","Sagas undo completed steps in reverse order.","Practice in lesson forty point one and design sd twenty six."])]),
V("o20-mcdc-1553","41.2–41.3 · Avionics","MC/DC coverage and the MIL-STD-1553 bus",[
S("title",sub=SUB,items=["What DO-178C asks for","MC/DC by example","1553 command words"],say=["This video covers two avionics topics from the Raytheon and Garmin roles: MC/DC test coverage, and the MIL-STD-1553 data bus."]),
S("analogy","Plain analogy: proving each light switch matters",items=["Hold every other switch still","Flip one switch","The bulb must change","Do that for every switch"],say=["Imagine proving each switch in a room really controls the light.","Hold every other switch still.","Flip just one.","The bulb must change.","Repeat for every switch. That's modified condition, decision coverage."]),
S("bullets","MC/DC for (A and B) or C",items=["A: TTF → true vs FTF → false","B: TTF → true vs TFF → false","C: TFF → false vs TFT → true","Four tests: TTF, FTF, TFF, TFT (n+1 for 3 conditions)","Required for DO-178C Level A software"],say=["Take the decision, A and B, or C.","For A, compare true true false, which is true, with false true false, which is false. Only A changed.","For B, compare true true false with true false false.","For C, compare true false false, which is false, with true false true, which is true.","So four tests cover three conditions: n plus one.","DO-178C requires this for level A software, where failure could be catastrophic."]),
S("flow","A 1553 command word (16 data bits)",items=["RT address: 5 bits","Transmit/receive: 1 bit","Subaddress: 5 bits (0 or 31 = mode code)","Word count: 5 bits (0 means 32)"],say=["The MIL-STD-1553 bus uses sixteen bit words, each sent with a sync pattern and a parity bit.","Five bits pick the remote terminal, one of thirty one addresses.","One bit says transmit or receive.","Five bits are the subaddress. Zero or thirty one means a mode code instead of data.","Five bits are the word count, where zero means thirty two."]),
S("recap","Recap",items=["MC/DC: each condition shown to independently change the outcome","Usually n+1 tests, but masking can block pairs","1553: RT 5 · T/R 1 · SA 5 · count 5","Major/minor frame schedules must fit the bus time","Labs: lessons 41.2 and 41.3; 06 problem p110"],say=["Recap.","MC/DC shows each condition independently changes the outcome.","Usually n plus one tests suffice, but masking can block pairs.","A 1553 command word is five, one, five and five bits.","Message schedules must fit each minor frame.","Practice in lessons forty one point two and forty one point three, and problem p one ten."])]),
]
